<?php $finished=(int)($stats['finished_attempts']??0); $passed=(int)($stats['passed_attempts']??0); ?>
<section class="ld-admin-page-head"><div><span class="ld-admin-kicker">DESEMPENHO</span><h1>Simulados</h1><p>Acompanhe as tentativas geradas pelo módulo dinâmico de simulados.</p></div></section>
<div class="ld-admin-stats-grid"><article class="ld-admin-stat-card"><div><span>Tentativas</span><strong><?= (int)($stats['total_attempts']??0) ?></strong><small>total</small></div></article><article class="ld-admin-stat-card"><div><span>Finalizadas</span><strong><?= $finished ?></strong><small>concluídas</small></div></article><article class="ld-admin-stat-card"><div><span>Aprovações</span><strong><?= $passed ?></strong><small><?= $finished?number_format(($passed/$finished)*100,1,',','.'):'0,0' ?>%</small></div></article><article class="ld-admin-stat-card"><div><span>Média</span><strong><?= number_format((float)($stats['average_percentage']??0),1,',','.') ?>%</strong><small><?= (int)($stats['students_count']??0) ?> aluno(s)</small></div></article></div>
<section class="ld-admin-panel"><div class="ld-admin-table-wrap"><table class="ld-admin-table"><thead><tr><th>Aluno</th><th>Escopo</th><th>Questões</th><th>Nota</th><th>Resultado</th><th>Data</th></tr></thead><tbody><?php if(empty($attempts)): ?><tr><td colspan="6">Nenhum simulado iniciado.</td></tr><?php endif; ?><?php foreach($attempts as $a): ?><tr><td><a class="ld-admin-link" href="<?= e(url('/admin/usuarios/'.(int)$a['user_id'])) ?>"><strong><?= e($a['student_name']) ?></strong></a><small><?= e($a['email']) ?></small></td><td><?= e($a['selection_mode']==='module'?($a['module_title']??'Módulo'):'Geral') ?></td><td><?= (int)$a['question_limit'] ?></td><td><?= number_format((float)$a['percentage'],1,',','.') ?>%</td><td><?= $a['status']==='finished'?($a['passed']?'Aprovado':'Reprovado'):e($a['status']) ?></td><td><?= e(date('d/m/Y H:i',strtotime($a['started_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
